+package main
+
+import (
+	"fmt"
+	mapset "github.com/deckarep/golang-set/v2"
+)
+
+func main() {
+	// Create a thread-safe set
+	safeSet := mapset.NewSet[int]()
+	safeSet.Add(1)
+	safeSet.Add(2)
+	safeSet.Add(3)
+
+	// Create a thread-unsafe set
+	unsafeSet := mapset.NewThreadUnsafeSet[int]()
+	unsafeSet.Add(3)
+	unsafeSet.Add(4)
+	unsafeSet.Add(5)
+
+	// Test ContainsAnyElement between different set types
+	result1 := safeSet.ContainsAnyElement(unsafeSet)
+	fmt.Printf("Safe set contains any element from unsafe set: %v\n", result1)
+
+	result2 := unsafeSet.ContainsAnyElement(safeSet)
+	fmt.Printf("Unsafe set contains any element from safe set: %v\n", result2)
+
+	// Test with sets that don't have common elements
+	unsafeSet2 := mapset.NewThreadUnsafeSet[int]()
+	unsafeSet2.Add(6)
+	unsafeSet2.Add(7)
+
+	result3 := safeSet.ContainsAnyElement(unsafeSet2)
+	fmt.Printf("Safe set contains any element from unsafe set2: %v\n", result3)
+}
